// One item per source: its key in Hyperfocus, the first page, and where the postings are in the answer.
return [
  { json: { source: 'arbeitnow', url: 'https://www.arbeitnow.com/api/job-board-api', itemsAt: 'data' } },
  // { json: { source: 'greenhouse:gitlab', url: 'https://boards-api.greenhouse.io/v1/boards/gitlab/jobs?content=true', itemsAt: 'jobs' } },
  // { json: { source: 'lever:spotify', url: 'https://api.lever.co/v0/postings/spotify?mode=json', itemsAt: '' } },
];

// One page of a source -> one batch for Hyperfocus (at most 500 postings), named so that sending it again changes nothing.
const source = $('Sources').item.json;
const answer = $json;
const items = (source.itemsAt ? answer[source.itemsAt] : Array.isArray(answer) ? answer : answer.data) || [];
const body = JSON.stringify({ source: source.source, items: items.slice(0, 500) });
const timestamp = String(Math.floor(Date.now() / 1000));
const key = `${source.source}:${$execution.id}:${$itemIndex}`;
return { json: { body, timestamp, key, toSign: `${timestamp}.${body}`, count: items.length } };
